    R=len(g); C=len(g[0])
    for c in range(C):
        for r in range(R):
            if grid[r][c]==4:
                rr=r
                while rr+1<R and grid[rr+1][c]!=9:
                    rr+=1
                    g[rr][c]=4
    return g

def transform(grid):
    g=[row[:] for row in grid]
    R=len(g); C=len(g[0])
    for c in range(C):
        rows4=[r for r in range(R) if grid[r][c]==4]
        if not rows4: continue
        top=min(rows4)
        rr=top
        while rr+1<R and grid[rr+1][c]!=9:
            rr+=1
        for r in range(top,rr+1):
            g[r][c]=4
    return g

def transform(grid):
    g=[row[:] for row in grid]
    R=len(g); C=len(g[0])
    rs=[r for r in range(R) for c in range(C) if grid[r][c]==9]
    if not rs: return g
    rmax=max(rs)
    for c in range(C):
        for r in range(R):
            if grid[r][c]==4:
                rr=r
                while rr+1<=rmax and grid[rr+1][c]!=9:
                    rr+=1
                    g[rr][c]=4
    return g
